ALTER TABLE public.competitions ADD COLUMN end_date date;
UPDATE public.competitions SET end_date = event_date;
CREATE OR REPLACE FUNCTION public.competitions_before_write() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.name := btrim(NEW.name); NEW.city := nullif(btrim(coalesce(NEW.city,'')),''); NEW.normalized_name := public.normalize_competition_name(NEW.name); NEW.year := extract(year from NEW.event_date)::int; NEW.end_date := coalesce(NEW.end_date,NEW.event_date); NEW.updated_at := now(); RETURN NEW; END $$;
ALTER TABLE public.competitions ADD CONSTRAINT competitions_date_range CHECK (end_date IS NOT NULL AND end_date >= event_date);
ALTER TABLE public.listings ADD COLUMN end_date date;
ALTER TABLE public.listings ADD COLUMN race_day date;
UPDATE public.listings l SET end_date = coalesce((SELECT c.end_date FROM public.competitions c WHERE c.id=l.competition_id),l.event_date);
ALTER TABLE public.listings ADD COLUMN expires_on date GENERATED ALWAYS AS (coalesce(race_day,end_date,event_date)) STORED;
ALTER TABLE public.listings ADD CONSTRAINT listings_date_range CHECK (end_date >= event_date AND (race_day IS NULL OR race_day BETWEEN event_date AND end_date));
CREATE OR REPLACE FUNCTION public.listings_event_dates_before_write() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.competitions; BEGIN IF TG_OP='UPDATE' AND OLD.expires_on < CURRENT_DATE AND (NEW.competition_id IS DISTINCT FROM OLD.competition_id OR NEW.race_day IS DISTINCT FROM OLD.race_day OR NEW.type IS DISTINCT FROM OLD.type OR NEW.format IS DISTINCT FROM OLD.format OR NEW.gender IS DISTINCT FROM OLD.gender OR NEW.skill_level IS DISTINCT FROM OLD.skill_level OR NEW.spots IS DISTINCT FROM OLD.spots OR NEW.description IS DISTINCT FROM OLD.description OR (NEW.is_active AND NOT OLD.is_active)) THEN RAISE EXCEPTION 'Expired listings cannot be edited or reactivated'; END IF; SELECT * INTO c FROM public.competitions WHERE id=NEW.competition_id; IF FOUND THEN NEW.event_date:=c.event_date; NEW.end_date:=c.end_date; NEW.competition:=c.name; NEW.location:=coalesce(c.city,''); IF NEW.competition_type IS DISTINCT FROM c.competition_type THEN RAISE EXCEPTION 'Competition type does not match event'; END IF; ELSE NEW.end_date:=coalesce(NEW.end_date,NEW.event_date); END IF; IF TG_OP='INSERT' AND coalesce(NEW.race_day,NEW.end_date,NEW.event_date)<CURRENT_DATE THEN RAISE EXCEPTION 'Choose an upcoming race day or event'; END IF; RETURN NEW; END $$;
CREATE TRIGGER listings_event_dates_before_write BEFORE INSERT OR UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION public.listings_event_dates_before_write();
ALTER POLICY "Upcoming competitions readable" ON public.competitions USING (end_date >= CURRENT_DATE);
ALTER POLICY "Users create competitions" ON public.competitions WITH CHECK (created_by=auth.uid() AND end_date>=CURRENT_DATE);
ALTER POLICY "Active listings public read" ON public.listings USING (is_active AND expires_on>=CURRENT_DATE);
CREATE INDEX listings_expiry_idx ON public.listings(expires_on) WHERE is_active;
CREATE INDEX competitions_end_date_idx ON public.competitions(end_date);
CREATE FUNCTION public.search_competition_ranges(_type text,_q text DEFAULT '') RETURNS TABLE(id uuid,name text,city text,event_date date,end_date date,listing_count bigint) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT c.id,c.name,c.city,c.event_date,c.end_date,(SELECT count(*) FROM public.listings l WHERE l.competition_id=c.id AND l.is_active AND l.expires_on>=CURRENT_DATE) FROM public.competitions c WHERE c.competition_type=_type AND c.end_date>=CURRENT_DATE AND (coalesce(_q,'')='' OR c.name ILIKE '%'||_q||'%' OR c.city ILIKE '%'||_q||'%' OR c.normalized_name LIKE '%'||public.normalize_competition_name(_q)||'%') ORDER BY c.event_date,c.name LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.search_competition_ranges(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.search_competition_ranges(text,text) TO anon,authenticated,service_role;
CREATE FUNCTION public.match_competition_ranges(_type text,_name text,_city text,_date date,_end_date date DEFAULT NULL) RETURNS TABLE(id uuid,name text,city text,event_date date,end_date date,listing_count bigint,score real) LANGUAGE sql STABLE SET search_path=public,extensions AS $$ SELECT c.id,c.name,c.city,c.event_date,c.end_date,(SELECT count(*) FROM public.listings l WHERE l.competition_id=c.id AND l.is_active AND l.expires_on>=CURRENT_DATE),extensions.similarity(c.normalized_name,public.normalize_competition_name(_name)) AS score FROM public.competitions c WHERE c.competition_type=_type AND c.end_date>=CURRENT_DATE AND c.event_date<=coalesce(_end_date,_date)+7 AND c.end_date>=_date-7 AND lower(coalesce(c.city,''))=lower(btrim(coalesce(_city,''))) AND extensions.similarity(c.normalized_name,public.normalize_competition_name(_name))>=0.3 ORDER BY score DESC,abs(c.event_date-_date) LIMIT 3 $$;
REVOKE ALL ON FUNCTION public.match_competition_ranges(text,text,text,date,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.match_competition_ranges(text,text,text,date,date) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.search_competitions(_type text,_q text DEFAULT '') RETURNS TABLE(id uuid,name text,city text,event_date date,listing_count bigint) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT r.id,r.name,r.city,r.event_date,r.listing_count FROM public.search_competition_ranges(_type,_q) r $$;
CREATE OR REPLACE FUNCTION public.match_competitions(_type text,_name text,_city text,_date date) RETURNS TABLE(id uuid,name text,city text,event_date date,listing_count bigint,score real) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT r.id,r.name,r.city,r.event_date,r.listing_count,r.score FROM public.match_competition_ranges(_type,_name,_city,_date,_date) r $$;